  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Buscar, conferir e navegar com ajuda', 'Um resultado de busca é uma pista, não uma garantia. Pergunte o que procura, observe quem publicou e quando, compare informações e peça ajuda antes de abrir links ou compartilhar dados.', '## Faça uma pergunta que possa ser pesquisada
Comece dizendo o que quer descobrir: “como as sementes viram plantas?” é mais útil que escrever uma frase longa sem foco. Escolha palavras principais e teste uma busca diferente se o resultado não responder à pergunta. No Ensino Fundamental I, use sites, cartões ou resultados selecionados por um adulto ou professor; não é necessário navegar sozinho em páginas abertas.

## Um resultado não é uma resposta pronta
A posição alta numa lista não prova que um texto seja correto, atual ou adequado. Observe o título, quem publicou, a data, o objetivo e de onde vêm as informações. Compare com outra fonte indicada pelo professor. Se um cartão de treino for inventado, ele deve estar identificado como simulação; não use exemplos fictícios como fatos reais. Diga o que conseguiu confirmar e o que ainda precisa perguntar.

## Pare antes de clicar ou compartilhar
Uma mensagem inesperada pode pedir nome completo, endereço, escola, senha, código ou foto. Não envie esses dados e não clique em link que cause dúvida. Feche ou pause e converse com um adulto de confiança ou com o professor. Senhas são secretas: não se compartilham com colegas, nem mesmo para “ganhar” um jogo. Uma oferta urgente ou uma promessa de prêmio não é motivo para agir depressa.

## Navegue com respeito e cuidado
Use conteúdo e imagens com permissão ou indicação de autoria. Trate outras pessoas com respeito, não publique mensagens ou fotos de alguém sem autorização e não repasse algo que possa machucar. Se aparecer conteúdo assustador, confuso ou inadequado, pare e peça ajuda; não é preciso responder nem investigar sozinho.

## Um roteiro para cada busca
1. Fale sua pergunta. 2. Use palavras principais. 3. Leia título, autoria, data e finalidade em fontes preparadas. 4. Compare antes de repetir uma informação. 5. Não compartilhe dados nem abra links duvidosos. 6. Peça ajuda quando algo surpreender ou preocupar.',
    'A turma quer descobrir como uma planta recebe água. A professora oferece dois cartões fictícios, claramente marcados como material de treino. Um tem título relacionado à pergunta, autoria identificada e explicação; o outro anuncia “resposta secreta grátis”, não informa quem escreveu e pede nome e escola. A turma escolhe primeiro o cartão informativo, compara com uma segunda fonte indicada pela professora e não preenche o pedido de dados. Como são cartões inventados, o grupo registra que praticou critérios de busca, não que comprovou um fato sobre plantas.', array['Diga em voz alta o que quer saber e destaque duas ou três palavras principais.', 'Veja quem publicou, quando e com qual propósito; posição na lista não é selo de verdade.', 'Compare uma informação com outra fonte escolhida por adulto ou professor.', 'Se pedirem dado pessoal, senha, código ou clique urgente, pare e peça ajuda.']::text[], 16, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-computing-search-safe-browse","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Fazer uma pergunta sobre um tema conhecido.","Reconhecer dados pessoais básicos e identificar um adulto de confiança."],"key_concepts":["Palavras-chave ajudam a formular uma busca, mas o resultado precisa ser avaliado.","Autoria, data, finalidade e comparação ajudam a julgar uma fonte sem prometer certeza automática.","Resultados de treino fictícios precisam ser rotulados e não são evidência de fatos reais.","Senha, código, endereço, escola e fotos pessoais não devem ser enviados a pedido inesperado.","Em páginas ou mensagens duvidosas, parar e buscar ajuda é uma ação competente."],"progression":[{"stage":"FOUNDATION","focus":"Transformar curiosidade em pergunta curta e reconhecer pedido de dado pessoal.","questionIds":["v5-comp-search-probe-01","v5-comp-search-probe-03","v5-comp-search-practice-01"]},{"stage":"APPLICATION","focus":"Usar palavras-chave e comparar cartões de resultado preparados.","questionIds":["v5-comp-search-practice-04","v5-comp-search-practice-08","v5-comp-search-practice-11"]},{"stage":"TRANSFER","focus":"Responder a mensagens, links e conteúdos novos com pausa, conferência e ajuda.","questionIds":["v5-comp-search-transfer-01","v5-comp-search-transfer-04","v5-comp-search-transfer-07"]},{"stage":"INTEGRATION","focus":"Justificar confiança limitada e proteger a privacidade em situações de pressão.","questionIds":["v5-comp-search-lock-01","v5-comp-search-lock-03","v5-comp-search-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar os critérios em busca e comunicação novas; o agendamento depende de mecanismo separado.","questionIds":["v5-comp-search-review-01","v5-comp-search-review-05","v5-comp-search-review-09"]}],"micro_explanations":[{"trigger":"FIRST_RESULT_TRUST","text":"A posição mostra onde o resultado apareceu, não se ele responde bem. Confira autoria, data, propósito e outra fonte indicada."},{"trigger":"PERSONAL_DATA_REQUEST","text":"Não envie senha, código, endereço, escola ou foto por pedido inesperado. Pare e consulte um adulto de confiança."},{"trigger":"SIMULATION_AS_FACT","text":"Cartão inventado serve para praticar critérios; ele não confirma um fato do mundo real."},{"trigger":"URGENT_LINK_PRESSURE","text":"Pressa e promessa de prêmio não são prova de segurança. Não clique; peça ajuda e use um canal conhecido."}],"remediations":[{"misconception":"RANKING_EQUALS_TRUST","prompt":"Cubra a posição na lista e compare apenas autoria, data, propósito e conteúdo. Qual desses dados ainda falta?"},{"misconception":"PERSONAL_DATA_FOR_REWARD","prompt":"Classifique o pedido como dado que pode ser público ou informação privada; em seguida, pratique dizer “vou pedir ajuda antes”."},{"misconception":"UNLABELED_SIMULATION","prompt":"Procure a indicação de que o material é fictício. Se ela não existe, não trate o exemplo como fonte real."},{"misconception":"LINK_CLICKED_UNDER_PRESSURE","prompt":"Pare antes de clicar, não responda e mostre a mensagem a um adulto por um canal conhecido."},{"misconception":"COPY_WITHOUT_SOURCE","prompt":"Anote o título e a instituição da fonte preparada pelo professor; diga com suas palavras o que conseguiu confirmar."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Jogue e aprenda: Estar online","publisher":"SaferNet Brasil / rede Insafe","url":"https://new.safernet.org.br/content/jogue-e-aprenda-estar-online","accessedOn":"2026-10-13","supports":["age-appropriate early online-safety activities","basic password and personal-data care"],"use":"Consulted for safety scope and age-appropriate framing; no activity, wording or question was copied."},{"title":"Proteção On-line Infantil","publisher":"Agência Nacional de Telecomunicações","url":"https://www.gov.br/anatel/pt-br/consumidor/mundo-digital/protecao-on-line-infantil","accessedOn":"2026-10-13","supports":["adult-supervised online safety","privacy and source reliability as topics for children"],"use":"Reference for safety constraints; this pack does not reproduce its exercises or claim a curriculum mapping."},{"title":"TIC Kids Online Brasil","publisher":"Cetic.br / NIC.br","url":"https://cetic.br/pesquisa/kids-online/","accessedOn":"2026-10-13","supports":["evidence on opportunities, risks and mediation in children''s and adolescents'' internet use"],"use":"Research-context reference; its population is ages 9–17 and is not treated as an age-specific outcome for this Fundamental I target."}],"copyright_note":"All search cards, examples, questions, options, explanations and activity instructions are original and hypothetical. Sources inform safety boundaries and context only; no source exercise or wording was copied. No official code mapping or human pedagogical approval is claimed.","authentic_activities":[{"id":"v5-computing-search-source-cards","title":"Qual cartão ajuda a responder?","instructions":"Com a mediação do professor, receba três cartões de resultados impressos ou em ambiente fechado. Um responde parcialmente à pergunta da turma com autoria e data; um é anúncio fictício claramente rotulado; outro é uma mensagem suspeita que solicita dados pessoais. Identifique palavras-chave da pergunta, compare autoria/data/finalidade, escolha o que merece conferência e explique por que não abriria o pedido de dados. Os exemplos devem estar marcados como simulação e não exigem que a criança pesquise na web aberta.","evidence":"Pergunta e palavras-chave, quadro simples de autoria/data/finalidade para os cartões, escolha justificada e uma ação segura diante do pedido de dados.","privacyGuard":"Usar apenas cartões fictícios e dados não pessoais. Não pedir nome completo, escola, endereço, foto, senha ou conta real. Não abrir links, cadastrar-se, enviar mensagens nem acessar buscas abertas; professor prepara os materiais e acompanha a atividade.","rubric":[{"criterion":"Pergunta e palavras-chave","emerging":"Não explicita o que procura.","developing":"Formula a pergunta com apoio, mas escolhe palavras pouco relacionadas.","proficient":"Formula uma pergunta compreensível e seleciona palavras principais que ajudam a procurar resposta."},{"criterion":"Leitura da fonte","emerging":"Escolhe apenas pela posição ou pelo título chamativo.","developing":"Observa um dado de fonte, com apoio para comparar.","proficient":"Compara autoria, data e finalidade e reconhece informação que ainda precisa confirmar."},{"criterion":"Decisão de segurança","emerging":"Compartilha ou aceitaria compartilhar dado privado.","developing":"Percebe o risco depois de uma sugestão do adulto.","proficient":"Não compartilha o dado e explica que vai parar e pedir ajuda."},{"criterion":"Limites da conclusão","emerging":"Apresenta cartão fictício como fato confirmado.","developing":"Reconhece que o professor forneceu o material, mas confunde simulação e fonte real.","proficient":"Identifica a simulação e separa prática de busca de comprovação de um fato real."}]}],"objective":"Formular uma busca simples, comparar resultados preparados quanto a autoria, data e propósito e escolher respostas seguras diante de pedidos de dados ou links inesperados.","common_mistake":"Confiar no primeiro resultado ou clicar em qualquer link, compartilhar informação pessoal para obter uma resposta e tratar um cartão inventado como fonte real.","estimated_minutes":16}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
