  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-comp-search-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"FORMULATE","contextFamily":"PERGUNTA_SOBRE_SEMENTES","statement":"A turma quer descobrir como uma semente começa a crescer. Qual frase ajuda mais a iniciar uma busca guiada?","options":["Como uma semente começa a crescer?","Pesquise tudo sobre todas as plantas para sempre.","Qual é o endereço de casa de quem plantou?","Clique no primeiro botão que aparecer."],"correctAnswer":"Como uma semente começa a crescer?","explanation":"A pergunta é específica e relacionada ao que a turma quer descobrir. O professor pode ajudar a escolher palavras-chave e fontes preparadas.","hint":"Escolha uma pergunta que diga claramente o que a turma quer saber.","errorFocus":"SEARCH_QUESTION_TOO_BROAD","misconceptions":{"Pesquise tudo sobre todas as plantas para sempre.":["QUESTION_TOO_BROAD"],"Qual é o endereço de casa de quem plantou?":["PERSONAL_DATA_IRRELEVANT"],"Clique no primeiro botão que aparecer.":["SEARCH_AS_RANDOM_CLICK"]},"position":1},{"id":"v5-comp-search-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"PEDIDO_DE_SENHA_NO_JOGO","statement":"Um jogo mostra uma janela inesperada: “Digite sua senha para ganhar uma estrela”. O que a criança deve fazer?","options":["Escrever a senha antes que a janela desapareça.","Parar sem digitar e chamar um adulto de confiança.","Pedir a senha de um colega para testar.","Publicar a senha no mural da turma."],"correctAnswer":"Parar sem digitar e chamar um adulto de confiança.","explanation":"Senha é privada. Uma solicitação inesperada deve ser interrompida e verificada com adulto de confiança, sem compartilhar credenciais.","hint":"Pense se uma senha deve ser enviada para receber uma recompensa.","errorFocus":"PASSWORD_SHARING","misconceptions":{"Escrever a senha antes que a janela desapareça.":["REWARD_PRESSURE"],"Pedir a senha de um colega para testar.":["CREDENTIALS_SHARED_WITH_PEER"],"Publicar a senha no mural da turma.":["PUBLIC_CREDENTIAL_DISCLOSURE"]},"position":2},{"id":"v5-comp-search-probe-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"EVALUATE","contextFamily":"CARTAO_RESULTADO_SEM_AUTORIA","statement":"Dois cartões fictícios respondem a uma pergunta. Um informa quem preparou o texto e quando; o outro não mostra autoria nem data. Qual próximo passo é mais cuidadoso?","options":["Escolher sempre o cartão mais colorido.","Afirmar que o primeiro está certo porque tem uma data.","Comparar as informações com outra fonte indicada pelo professor e perguntar sobre o cartão sem autoria.","Usar os dois como fatos sem conferir."],"correctAnswer":"Comparar as informações com outra fonte indicada pelo professor e perguntar sobre o cartão sem autoria.","explanation":"Autoria e data ajudam a avaliar, mas não garantem correção sozinhas. Comparar e pedir orientação é uma ação cuidadosa.","hint":"Uma pista de autoria ajuda, mas que outra checagem pode ser feita?","errorFocus":"SOURCE_CUE_AS_CERTAINTY","misconceptions":{"Escolher sempre o cartão mais colorido.":["VISUAL_DESIGN_AS_TRUST"],"Afirmar que o primeiro está certo porque tem uma data.":["DATE_AS_CERTAINTY"],"Usar os dois como fatos sem conferir.":["SOURCE_NOT_CHECKED"]},"position":3},{"id":"v5-comp-search-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"SELECT","contextFamily":"PALAVRAS_CHAVE_BORBOLETA","statement":"Para buscar informação sobre o que uma borboleta come, quais palavras principais ajudam mais?","options":["coisa bonita internet","meu nome endereço","clique agora prêmio","borboleta alimentação"],"correctAnswer":"borboleta alimentação","explanation":"As palavras se relacionam diretamente com o tema da pergunta. Depois, resultados preparados ainda precisam ser lidos e comparados.","hint":"Escolha palavras ligadas ao assunto e ao que quer descobrir.","errorFocus":"KEYWORDS_NOT_RELATED","misconceptions":{"coisa bonita internet":["KEYWORDS_TOO_VAGUE"],"meu nome endereço":["PERSONAL_DATA_AS_SEARCH_TERM"],"clique agora prêmio":["ADVERTISEMENT_AS_QUERY"]},"position":1},{"id":"v5-comp-search-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"CARTOES_COM_DATAS","statement":"Um cartão de treino sobre chuva traz uma data antiga; outro, preparado por uma instituição indicada pela professora, traz uma data recente. O que a data ajuda a avaliar?","options":["Se o cartão responde a uma pergunta sobre o presente ou pode estar desatualizado.","Se o cartão é automaticamente verdadeiro.","Se o autor é inteligente.","Se a criança deve compartilhar endereço."],"correctAnswer":"Se o cartão responde a uma pergunta sobre o presente ou pode estar desatualizado.","explanation":"Data importa quando a informação pode mudar. Ela não prova, sozinha, que um conteúdo seja verdadeiro ou falso.","hint":"Pergunte se a resposta depende de quando foi publicada.","errorFocus":"DATE_AS_CERTAINTY","misconceptions":{"Se o cartão é automaticamente verdadeiro.":["DATE_AS_CERTAINTY"],"Se o autor é inteligente.":["AUTHOR_RANKING_AS_TRUST"],"Se a criança deve compartilhar endereço.":["PERSONAL_DATA_IRRELEVANT"]},"position":2},{"id":"v5-comp-search-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"RESULTADO_MARCADO_ANUNCIO","statement":"Um resultado de busca vem acompanhado da palavra “Anúncio” e oferece um brinquedo. A turma procura informações sobre como cuidar de uma horta. O que deve fazer?","options":["Tratar a oferta como resposta porque apareceu primeiro.","Perceber que é uma publicidade e voltar à pergunta da horta com ajuda do professor.","Enviar o telefone da família para receber mais informações.","Afirmar que todo anúncio é falso sem ler."],"correctAnswer":"Perceber que é uma publicidade e voltar à pergunta da horta com ajuda do professor.","explanation":"Um anúncio tem finalidade de promover algo, diferente de responder à pergunta de pesquisa. A classificação não significa que toda publicidade seja falsa.","hint":"Observe o rótulo e pergunte qual é o objetivo daquele resultado.","errorFocus":"ADVERTISEMENT_PURPOSE","misconceptions":{"Tratar a oferta como resposta porque apareceu primeiro.":["RANKING_EQUALS_RELEVANCE"],"Enviar o telefone da família para receber mais informações.":["PERSONAL_DATA_FOR_OFFER"],"Afirmar que todo anúncio é falso sem ler.":["ADVERTISEMENT_AS_ALWAYS_FALSE"]},"position":3},{"id":"v5-comp-search-practice-04","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"DADO_PESSOAL_NO_CADASTRO","statement":"Uma página de jogo pede nome completo, endereço e senha para liberar uma figurinha. Qual resposta protege a criança?","options":["Preencher tudo para terminar rápido.","Usar a senha de um adulto sem contar a ele.","Parar e pedir ajuda, sem enviar os dados.","Mandar os dados a um colega para decidir."],"correctAnswer":"Parar e pedir ajuda, sem enviar os dados.","explanation":"Nome completo, endereço e senha são informações privadas. Um pedido inesperado não deve ser atendido sem orientação de adulto responsável.","hint":"Não é preciso fornecer informações privadas para uma figurinha de jogo.","errorFocus":"PERSONAL_DATA_REQUEST","misconceptions":{"Preencher tudo para terminar rápido.":["URGENT_COMPLETION_PRESSURE"],"Usar a senha de um adulto sem contar a ele.":["CREDENTIALS_SHARED_WITH_PEER"],"Mandar os dados a um colega para decidir.":["PERSONAL_DATA_SHARED_WITHOUT_NEED"]},"position":4},{"id":"v5-comp-search-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"AUTORIA_DE_CARTAO_ESCOLAR","statement":"Dois cartões fictícios falam sobre uma brincadeira. O primeiro diz quem o preparou e para qual atividade; o segundo não informa origem. O que é correto dizer?","options":["O primeiro é sempre verdade porque tem autor.","O segundo deve ser compartilhado para descobrir quem o escreveu.","A autoria não importa em nenhuma busca.","O primeiro tem pistas de autoria e propósito que ajudam a avaliar; ainda pode ser comparado."],"correctAnswer":"O primeiro tem pistas de autoria e propósito que ajudam a avaliar; ainda pode ser comparado.","explanation":"Autoria e finalidade são pistas úteis, não garantias absolutas. A comparação ajuda a perceber o que ainda falta confirmar.","hint":"Trate autoria como uma pista para investigar, não como selo automático.","errorFocus":"AUTHORSHIP_AS_CERTAINTY","misconceptions":{"O primeiro é sempre verdade porque tem autor.":["AUTHORSHIP_AS_CERTAINTY"],"O segundo deve ser compartilhado para descobrir quem o escreveu.":["UNVERIFIED_CONTENT_AMPLIFIED"],"A autoria não importa em nenhuma busca.":["SOURCE_CUE_IGNORED"]},"position":5},{"id":"v5-comp-search-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"LINK_COM_PROMESSA_URGENTE","statement":"Uma mensagem diz: “Clique agora para ganhar um prêmio antes que acabe”. O endereço é desconhecido. Qual ação é mais segura?","options":["Não clicar nem encaminhar e pedir ajuda a um adulto.","Clicar rapidamente para não perder a chance.","Encaminhar para toda a turma.","Digitar a senha para ver se o prêmio é real."],"correctAnswer":"Não clicar nem encaminhar e pedir ajuda a um adulto.","explanation":"Urgência e recompensa não confirmam segurança. Sem conhecer o link, a criança deve parar e pedir ajuda.","hint":"A mensagem tenta apressar a decisão; você pode pausar.","errorFocus":"URGENT_LINK_PRESSURE","misconceptions":{"Clicar rapidamente para não perder a chance.":["SCARCITY_PRESSURE"],"Encaminhar para toda a turma.":["UNVERIFIED_CONTENT_AMPLIFIED"],"Digitar a senha para ver se o prêmio é real.":["PASSWORD_SHARING"]},"position":6},{"id":"v5-comp-search-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"CARTAO_FICTICIO_ROTULADO","statement":"Um cartão usado em aula diz no topo “Exemplo inventado para praticar”. Como a turma deve usar o texto?","options":["Como prova de que o fato descrito aconteceu.","Como simulação para praticar perguntas sobre autoria e propósito.","Como notícia atual porque tem formato de cartão.","Como conteúdo que não pode ser discutido."],"correctAnswer":"Como simulação para praticar perguntas sobre autoria e propósito.","explanation":"O rótulo informa que o material é inventado. Ele serve para praticar critérios de leitura, não para confirmar o fato narrado.","hint":"Leia a indicação sobre a origem do material.","errorFocus":"SIMULATION_AS_FACT","misconceptions":{"Como prova de que o fato descrito aconteceu.":["SIMULATION_AS_FACT"],"Como notícia atual porque tem formato de cartão.":["FORMAT_AS_AUTHENTICITY"],"Como conteúdo que não pode ser discutido.":["SIMULATION_NOT_USEFUL"]},"position":7},{"id":"v5-comp-search-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"RESPOSTAS_DIFERENTES_EM_FONTES","statement":"Duas fontes preparadas pela professora dão explicações diferentes para uma pergunta simples. O que a turma deve fazer?","options":["Escolher a que tem letras maiores.","Copiar as duas sem avisar que divergem.","Comparar autoria, data e explicação, e pedir ajuda para entender a diferença.","Escolher a primeira porque aparece antes."],"correctAnswer":"Comparar autoria, data e explicação, e pedir ajuda para entender a diferença.","explanation":"Divergência é um motivo para conferir e conversar, não para escolher por aparência ou posição.","hint":"Procure pistas sobre origem e conteúdo, depois converse sobre o que continua incerto.","errorFocus":"CONFLICTING_SOURCES","misconceptions":{"Escolher a que tem letras maiores.":["VISUAL_DESIGN_AS_TRUST"],"Copiar as duas sem avisar que divergem.":["CONFLICT_HIDDEN"],"Escolher a primeira porque aparece antes.":["RANKING_EQUALS_TRUST"]},"position":8},{"id":"v5-comp-search-practice-09","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"FOTO_DE_COLEGA_NO_POST","statement":"Uma criança quer publicar a foto de um colega em uma atividade. Qual atitude demonstra cuidado?","options":["Publicar sem perguntar porque a foto ficou bonita.","Adicionar endereço e nome completo para identificar a pessoa.","Enviar a foto a desconhecidos para receber opinião.","Pedir autorização ao colega e seguir a orientação do adulto responsável antes de compartilhar."],"correctAnswer":"Pedir autorização ao colega e seguir a orientação do adulto responsável antes de compartilhar.","explanation":"Imagem de outra pessoa envolve privacidade. Pedir autorização e seguir a orientação responsável evita exposição indevida.","hint":"A imagem também pode identificar alguém.","errorFocus":"IMAGE_SHARED_WITHOUT_PERMISSION","misconceptions":{"Publicar sem perguntar porque a foto ficou bonita.":["AESTHETIC_AS_PERMISSION"],"Adicionar endereço e nome completo para identificar a pessoa.":["PERSONAL_DATA_OVERDISCLOSURE"],"Enviar a foto a desconhecidos para receber opinião.":["IMAGE_SHARED_WITH_UNKNOWN_AUDIENCE"]},"position":9},{"id":"v5-comp-search-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"DUPLICATA_DE_IMAGEM","statement":"Um estudante quer colocar uma imagem encontrada em um trabalho público. Qual próximo passo é mais responsável?","options":["Verificar permissão ou licença com o professor e registrar a autoria quando solicitado.","Usar qualquer imagem porque apareceu numa busca.","Apagar o nome de quem criou para a imagem parecer própria.","Afirmar que toda imagem da internet é gratuita."],"correctAnswer":"Verificar permissão ou licença com o professor e registrar a autoria quando solicitado.","explanation":"Encontrar uma imagem não significa ter permissão para qualquer uso. Verificar licença e atribuição é parte do cuidado ao reutilizar conteúdo.","hint":"Procure informação sobre quem criou e quais usos são permitidos.","errorFocus":"CONTENT_REUSE_WITHOUT_PERMISSION","misconceptions":{"Usar qualquer imagem porque apareceu numa busca.":["SEARCH_RESULT_AS_LICENSE"],"Apagar o nome de quem criou para a imagem parecer própria.":["AUTHORSHIP_REMOVED"],"Afirmar que toda imagem da internet é gratuita.":["ONLINE_CONTENT_AS_PUBLIC_DOMAIN"]},"position":10},{"id":"v5-comp-search-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"PERGUNTA_E_FONTE_DE_CUIDADO","statement":"A turma encontra uma página com título chamativo sobre cuidar de um animal, mas sem autor nem data. Qual decisão demonstra leitura cuidadosa?","options":["Repetir a recomendação porque o título parece convincente.","Comparar com material indicado por adulto e pedir orientação antes de seguir qualquer instrução sobre o animal.","Testar a recomendação em um animal sem perguntar.","Compartilhar a página para descobrir se alguém concorda."],"correctAnswer":"Comparar com material indicado por adulto e pedir orientação antes de seguir qualquer instrução sobre o animal.","explanation":"Conteúdo sobre cuidado de seres vivos requer fonte confiável e orientação adulta. Título chamativo não é evidência.","hint":"Não transforme uma busca sem autoria em instrução para agir.","errorFocus":"UNVERIFIED_INSTRUCTION_ACTED_ON","misconceptions":{"Repetir a recomendação porque o título parece convincente.":["TITLE_AS_EVIDENCE"],"Testar a recomendação em um animal sem perguntar.":["UNVERIFIED_INSTRUCTION_ACTED_ON"],"Compartilhar a página para descobrir se alguém concorda.":["UNVERIFIED_CONTENT_AMPLIFIED"]},"position":11},{"id":"v5-comp-search-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"MENSAGEM_DE_CODIGO_DE_CONFIRMACAO","statement":"Uma mensagem inesperada pede um código que chegou ao telefone da família e diz que a conta será bloqueada em dois minutos. O que fazer?","options":["Enviar o código para evitar o bloqueio.","Publicar o código na conversa da turma.","Não compartilhar o código e chamar o adulto responsável para verificar por um canal conhecido.","Tentar adivinhar outro código."],"correctAnswer":"Não compartilhar o código e chamar o adulto responsável para verificar por um canal conhecido.","explanation":"Código de confirmação pode permitir acesso a uma conta. A ameaça de bloqueio não justifica compartilhá-lo; verifique com responsável por canal conhecido.","hint":"Código também funciona como chave; mantenha-o privado.","errorFocus":"VERIFICATION_CODE_SHARING","misconceptions":{"Enviar o código para evitar o bloqueio.":["THREAT_PRESSURE"],"Publicar o código na conversa da turma.":["PUBLIC_CREDENTIAL_DISCLOSURE"],"Tentar adivinhar outro código.":["CODE_GUESSING_AS_RESPONSE"]},"position":1},{"id":"v5-comp-search-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"TRES_RESULTADOS_SOBRE_PLANTIO","statement":"Para saber quando uma horta escolar será irrigada, há um aviso recente da própria escola e dois textos gerais antigos. Qual fonte inicial responde mais diretamente à pergunta local?","options":["O texto antigo com mais imagens.","Qualquer resultado que apareça em primeiro lugar.","Uma mensagem anônima encaminhada sem contexto.","O aviso recente da escola, conferindo a data e perguntando ao responsável se houver dúvida."],"correctAnswer":"O aviso recente da escola, conferindo a data e perguntando ao responsável se houver dúvida.","explanation":"A fonte da própria escola e recente é mais diretamente relacionada a um horário local, embora uma dúvida possa exigir confirmação com responsável.","hint":"A pergunta trata de uma decisão específica da escola, não de orientação geral.","errorFocus":"SOURCE_RELEVANCE","misconceptions":{"O texto antigo com mais imagens.":["VISUAL_DESIGN_AS_RELEVANCE"],"Qualquer resultado que apareça em primeiro lugar.":["RANKING_EQUALS_RELEVANCE"],"Uma mensagem anônima encaminhada sem contexto.":["ANONYMOUS_FORWARD_AS_SOURCE"]},"position":2},{"id":"v5-comp-search-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"TITULO_IGUAL_AUTOR_DIFERENTE","statement":"Dois cartões de treino têm títulos parecidos, mas autores e datas diferentes. Qual comparação ajuda a turma a escolher qual conferir primeiro?","options":["Comparar autoria, data, finalidade e se o texto responde à pergunta, sem decidir só pelo título.","Escolher sempre o cartão com mais cores.","Escolher o que pede dados pessoais para liberar a resposta.","Supor que títulos iguais garantem conteúdo igual."],"correctAnswer":"Comparar autoria, data, finalidade e se o texto responde à pergunta, sem decidir só pelo título.","explanation":"Título parecido não garante mesma origem ou qualidade. Critérios combinados ajudam a escolher uma fonte para conferência, sem prometer certeza automática.","hint":"Use mais de uma pista do cartão.","errorFocus":"TITLE_MATCH_AS_SOURCE_EQUIVALENCE","misconceptions":{"Escolher sempre o cartão com mais cores.":["VISUAL_DESIGN_AS_TRUST"],"Escolher o que pede dados pessoais para liberar a resposta.":["PERSONAL_DATA_FOR_REWARD"],"Supor que títulos iguais garantem conteúdo igual.":["TITLE_MATCH_AS_SOURCE_EQUIVALENCE"]},"position":3},{"id":"v5-comp-search-transfer-04","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"RESPOND","contextFamily":"CONTEUDO_ASSUSTADOR_INESPERADO","statement":"Ao abrir uma atividade supervisionada, aparece um conteúdo assustador que não fazia parte da aula. Qual resposta é apropriada?","options":["Continuar abrindo páginas parecidas para investigar sozinho.","Parar, afastar-se do conteúdo e avisar o professor ou adulto de confiança.","Enviar o conteúdo para colegas sem explicar.","Responder à página com dados da família."],"correctAnswer":"Parar, afastar-se do conteúdo e avisar o professor ou adulto de confiança.","explanation":"A criança não precisa investigar ou responder a conteúdo inesperado. Parar e chamar um adulto permite lidar com a situação com apoio.","hint":"Você pode sair da situação e chamar alguém responsável.","errorFocus":"UNSAFE_CONTENT_ESCALATION","misconceptions":{"Continuar abrindo páginas parecidas para investigar sozinho.":["UNSUPERVISED_INVESTIGATION"],"Enviar o conteúdo para colegas sem explicar.":["DISTRESSING_CONTENT_AMPLIFIED"],"Responder à página com dados da família.":["PERSONAL_DATA_DISCLOSURE"]},"position":4},{"id":"v5-comp-search-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"CARTAO_REAL_E_CARTAO_SIMULADO","statement":"Um material de aula mistura uma fonte indicada pela professora e um cartão inventado para exercício. Como apresentar a conclusão do grupo?","options":["Apresentar o cartão inventado como notícia real.","Retirar os rótulos para a apresentação ficar mais bonita.","Dizer qual informação veio da fonte e qual foi usada apenas como simulação.","Afirmar que toda simulação é falsa e inútil."],"correctAnswer":"Dizer qual informação veio da fonte e qual foi usada apenas como simulação.","explanation":"Transparência sobre origem evita confundir prática com evidência real. Uma simulação é útil para exercitar critérios, mas não confirma o fato.","hint":"Mantenha visível a origem de cada material.","errorFocus":"SIMULATION_AS_FACT","misconceptions":{"Apresentar o cartão inventado como notícia real.":["SIMULATION_AS_FACT"],"Retirar os rótulos para a apresentação ficar mais bonita.":["SOURCE_PROVENANCE_HIDDEN"],"Afirmar que toda simulação é falsa e inútil.":["SIMULATION_NOT_USEFUL"]},"position":5},{"id":"v5-comp-search-transfer-06","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"PESQUISA_COM_ADULTO","statement":"Uma criança precisa encontrar informação para um trabalho e não sabe se um site é adequado. Qual ação permite continuar com segurança?","options":["Abrir vários links desconhecidos até algum parecer bom.","Digitar a senha da família na página para pedir acesso.","Pedir a um desconhecido em uma conversa privada.","Usar um resultado preparado ou recomendado pelo professor e perguntar antes de abrir outros."],"correctAnswer":"Usar um resultado preparado ou recomendado pelo professor e perguntar antes de abrir outros.","explanation":"A mediação do professor e fontes selecionadas ajudam a criança a pesquisar sem navegação aberta e sem expor dados.","hint":"Use o canal de ajuda que já está combinado na atividade.","errorFocus":"SAFE_SOURCE_SELECTION","misconceptions":{"Abrir vários links desconhecidos até algum parecer bom.":["UNSUPERVISED_BROWSING"],"Digitar a senha da família na página para pedir acesso.":["PASSWORD_SHARING"],"Pedir a um desconhecido em uma conversa privada.":["UNKNOWN_CONTACT_AS_HELP"]},"position":6},{"id":"v5-comp-search-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PERFIL_QUE_PROMETE_PONTOS","statement":"Um perfil desconhecido promete pontos para quem publicar uma foto com uniforme e marcar a escola. Qual avaliação é mais cuidadosa?","options":["A foto pode revelar identidade e local; não publique e confirme com a escola por um canal conhecido.","A promessa prova que o perfil pertence à escola.","Marcar a escola torna a publicação privada.","Enviar a senha junto com a foto ajuda a validar o perfil."],"correctAnswer":"A foto pode revelar identidade e local; não publique e confirme com a escola por um canal conhecido.","explanation":"Imagem e uniforme podem expor informação identificável. Confirme qualquer solicitação por canal oficial conhecido e não compartilhe senha.","hint":"Considere o que outras pessoas poderiam descobrir pela imagem.","errorFocus":"IDENTIFIABLE_IMAGE_DISCLOSURE","misconceptions":{"A promessa prova que o perfil pertence à escola.":["IMPERSONATION_AS_AUTHENTICITY"],"Marcar a escola torna a publicação privada.":["TAG_AS_PRIVACY_CONTROL"],"Enviar a senha junto com a foto ajuda a validar o perfil.":["PASSWORD_SHARING"]},"position":7},{"id":"v5-comp-search-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"PRIMEIRO_RESULTADO_NAO_RESPONDE","statement":"O primeiro cartão de busca fala de um tema parecido, mas não responde à pergunta da turma. O que é melhor fazer?","options":["Copiar a resposta mesmo sem relação direta.","Reformular as palavras-chave com ajuda e comparar outro resultado preparado.","Repetir a busca enviando endereço da escola.","Concluir que a pergunta não pode ser pesquisada."],"correctAnswer":"Reformular as palavras-chave com ajuda e comparar outro resultado preparado.","explanation":"Uma busca pode precisar de palavras mais específicas. A criança pode pedir apoio e testar outra fonte selecionada sem revelar dados pessoais.","hint":"Ajuste a pergunta ou as palavras principais, não os dados pessoais.","errorFocus":"SEARCH_ITERATION","misconceptions":{"Copiar a resposta mesmo sem relação direta.":["RELEVANCE_IGNORED"],"Repetir a busca enviando endereço da escola.":["PERSONAL_DATA_AS_SEARCH_TERM"],"Concluir que a pergunta não pode ser pesquisada.":["SEARCH_FAILURE_AS_IMPOSSIBILITY"]},"position":1},{"id":"v5-comp-search-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"SENHA_E_NOME_DE_USUARIO","statement":"Um colega quer ajudar a entrar em um jogo e pede a senha da conta. Qual resposta protege a conta e mantém a amizade?","options":["Entregar a senha porque o colega é conhecido.","Trocar a senha por uma palavra fácil e publicar no grupo.","Dizer que senha é privada e pedir ajuda a um adulto se o acesso estiver com problema.","Pedir a senha de outra pessoa para comparar."],"correctAnswer":"Dizer que senha é privada e pedir ajuda a um adulto se o acesso estiver com problema.","explanation":"Mesmo entre colegas, senhas devem permanecer privadas. Um adulto responsável pode ajudar sem que a criança divulgue a credencial.","hint":"Uma pessoa amiga não precisa saber sua senha para continuar sendo amiga.","errorFocus":"CREDENTIALS_SHARED_WITH_PEER","misconceptions":{"Entregar a senha porque o colega é conhecido.":["TRUST_AS_CREDENTIAL_PERMISSION"],"Trocar a senha por uma palavra fácil e publicar no grupo.":["PUBLIC_CREDENTIAL_DISCLOSURE"],"Pedir a senha de outra pessoa para comparar.":["RECIPROCAL_CREDENTIAL_SHARING"]},"position":2},{"id":"v5-comp-search-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"FONTE_COM_AUTOR_E_PUBLICIDADE","statement":"Um cartão com autoria identificada também contém um anúncio claramente separado. O que a turma deve fazer ao usar a explicação do cartão?","options":["Usar o anúncio como prova da explicação.","Ignorar toda a informação porque existe um anúncio.","Afirmar que a autoria torna qualquer anúncio neutro.","Separar a explicação da publicidade e comparar o conteúdo com outra fonte indicada."],"correctAnswer":"Separar a explicação da publicidade e comparar o conteúdo com outra fonte indicada.","explanation":"Uma fonte pode conter partes com propósitos diferentes. A turma deve distinguir conteúdo informativo e publicidade e conferir a explicação.","hint":"Observe os rótulos e a finalidade de cada parte.","errorFocus":"ADVERTISING_AND_INFORMATION_MIXED","misconceptions":{"Usar o anúncio como prova da explicação.":["ADVERTISEMENT_AS_EVIDENCE"],"Ignorar toda a informação porque existe um anúncio.":["SOURCE_REJECTED_WITHOUT_READING"],"Afirmar que a autoria torna qualquer anúncio neutro.":["AUTHORSHIP_AS_NEUTRALITY"]},"position":3},{"id":"v5-comp-search-lock-04","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"RESPOND","contextFamily":"COLEGA_ENVIA_LINK_DESCONHECIDO","statement":"Um colega envia um link que diz “veja sem contar para ninguém”. A criança não sabe o que há nele. Qual resposta é mais segura?","options":["Não abrir e mostrar a mensagem a um adulto de confiança.","Abrir escondido para descobrir.","Pedir que o colega envie uma senha também.","Encaminhar para outra turma."],"correctAnswer":"Não abrir e mostrar a mensagem a um adulto de confiança.","explanation":"Segredo e desconhecimento do conteúdo são motivos para pausar. Um adulto pode ajudar a verificar sem espalhar o link.","hint":"Você não precisa aceitar uma instrução para esconder algo que causa dúvida.","errorFocus":"SECRECY_PRESSURE","misconceptions":{"Abrir escondido para descobrir.":["SECRECY_PRESSURE"],"Pedir que o colega envie uma senha também.":["RECIPROCAL_CREDENTIAL_SHARING"],"Encaminhar para outra turma.":["UNVERIFIED_CONTENT_AMPLIFIED"]},"position":4},{"id":"v5-comp-search-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EXPLAIN","contextFamily":"RESPOSTA_CONFIRMADA_POR_DUAS_FONTES","statement":"Duas fontes recomendadas pelo professor concordam sobre uma informação, mas não mostram todos os detalhes. Como apresentar o resultado?","options":["Afirmar que duas fontes provam qualquer detalhe relacionado.","Dizer o que as fontes sustentam e indicar o que ainda não foi verificado.","Esconder as fontes para que a resposta pareça própria.","Inventar os detalhes que faltam."],"correctAnswer":"Dizer o que as fontes sustentam e indicar o que ainda não foi verificado.","explanation":"Concordância entre fontes dá apoio ao ponto que elas apresentam, mas não autoriza inventar ou ampliar detalhes ausentes.","hint":"Compare o alcance da resposta com o que as fontes realmente dizem.","errorFocus":"EVIDENCE_SCOPE_OVERCLAIM","misconceptions":{"Afirmar que duas fontes provam qualquer detalhe relacionado.":["SOURCE_AGREEMENT_AS_UNIVERSAL_PROOF"],"Esconder as fontes para que a resposta pareça própria.":["SOURCE_ATTRIBUTION_OMITTED"],"Inventar os detalhes que faltam.":["MISSING_EVIDENCE_FILLED_BY_GUESS"]},"position":5},{"id":"v5-comp-search-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"SELECT","contextFamily":"BUSCA_POR_RECEITA_DE_MASSA","statement":"A turma quer saber como preparar uma massa de modelar caseira para uma atividade. Qual é o melhor primeiro passo?","options":["Abrir qualquer resultado sem ler ingredientes.","Informar endereço e telefone para receber a receita.","Perguntar ao professor e usar uma instrução preparada para a turma.","Misturar produtos de limpeza para testar."],"correctAnswer":"Perguntar ao professor e usar uma instrução preparada para a turma.","explanation":"Uma atividade com materiais deve seguir instrução selecionada por adulto e cuidados de segurança; não se deve testar combinações desconhecidas.","hint":"Escolha um caminho supervisionado antes de usar materiais.","errorFocus":"SAFE_SOURCE_SELECTION","misconceptions":{"Abrir qualquer resultado sem ler ingredientes.":["UNSUPERVISED_INSTRUCTION"],"Informar endereço e telefone para receber a receita.":["PERSONAL_DATA_FOR_CONTENT"],"Misturar produtos de limpeza para testar.":["UNSAFE_EXPERIMENT"]},"position":1},{"id":"v5-comp-search-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"LISTA_DE_RESULTADOS_COM_ORDEM","statement":"Um resultado aparece no topo da lista e outro, recomendado pela professora, aparece mais abaixo. Qual afirmação é correta?","options":["O primeiro é sempre melhor porque está no topo.","O resultado de baixo deve ser falso.","A turma deve clicar nos dois sem supervisão.","A posição sozinha não garante qualidade; autoria, data e relação com a pergunta também importam."],"correctAnswer":"A posição sozinha não garante qualidade; autoria, data e relação com a pergunta também importam.","explanation":"Ordenação da lista não substitui avaliação de fonte. Considere várias pistas e siga a seleção segura do professor.","hint":"O que mais você sabe além da posição?","errorFocus":"RANKING_EQUALS_TRUST","misconceptions":{"O primeiro é sempre melhor porque está no topo.":["RANKING_EQUALS_TRUST"],"O resultado de baixo deve ser falso.":["RANKING_REVERSED_AS_FALSE"],"A turma deve clicar nos dois sem supervisão.":["UNSUPERVISED_BROWSING"]},"position":2},{"id":"v5-comp-search-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"NOME_COMPLETO_E_ESCOLA","statement":"Um formulário de brincadeira pede nome completo e escola da criança, mas essas informações não são necessárias para jogar. O que fazer?","options":["Parar e pedir a um adulto para verificar, sem enviar as informações.","Preencher para não perder a vez.","Inventar dados de um colega.","Publicar os dados no chat para perguntar."],"correctAnswer":"Parar e pedir a um adulto para verificar, sem enviar as informações.","explanation":"Informação que identifica uma criança não deve ser enviada a pedido inesperado. Pare e consulte um adulto responsável.","hint":"Se o dado não é necessário, não o envie antes de conversar com adulto.","errorFocus":"PERSONAL_DATA_REQUEST","misconceptions":{"Preencher para não perder a vez.":["REWARD_PRESSURE"],"Inventar dados de um colega.":["OTHERS_DATA_MISUSE"],"Publicar os dados no chat para perguntar.":["PUBLIC_PERSONAL_DATA_DISCLOSURE"]},"position":3},{"id":"v5-comp-search-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"TEXTO_FICTICIO_SEM_ROTULO","statement":"Um cartão de aula contém um dado inventado, mas não informa que é uma simulação. Antes de apresentá-lo, qual ação é necessária?","options":["Apresentá-lo como verdade porque foi impresso.","Adicionar ou confirmar a identificação de simulação com o professor e não usá-lo como fonte factual.","Retirar a autoria de outros materiais.","Compartilhar a frase sem mencionar de onde veio."],"correctAnswer":"Adicionar ou confirmar a identificação de simulação com o professor e não usá-lo como fonte factual.","explanation":"A origem deve estar clara. Se o cartão é inventado, precisa ser identificado e não pode servir como comprovação de um fato.","hint":"Pergunte ao professor de onde veio o cartão antes de divulgar a informação.","errorFocus":"SOURCE_PROVENANCE_HIDDEN","misconceptions":{"Apresentá-lo como verdade porque foi impresso.":["FORMAT_AS_AUTHENTICITY"],"Retirar a autoria de outros materiais.":["AUTHORSHIP_REMOVED"],"Compartilhar a frase sem mencionar de onde veio.":["SOURCE_ATTRIBUTION_OMITTED"]},"position":4},{"id":"v5-comp-search-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"MENSAGEM_PEDINDO_FOTO","statement":"Uma conta desconhecida pede uma foto para “confirmar que você é aluno da escola”. Qual resposta protege a criança?","options":["Enviar a foto e o nome da escola.","Pedir uma foto de volta antes de enviar.","Não enviar e conversar com um adulto de confiança ou com a escola por canal conhecido.","Publicar a solicitação para todos responderem."],"correctAnswer":"Não enviar e conversar com um adulto de confiança ou com a escola por canal conhecido.","explanation":"Foto e vínculo escolar podem identificar a criança. Confirme a solicitação com um adulto ou canal oficial conhecido.","hint":"Não use a própria resposta ao desconhecido para descobrir se ele é confiável.","errorFocus":"IDENTIFIABLE_IMAGE_DISCLOSURE","misconceptions":{"Enviar a foto e o nome da escola.":["PERSONAL_DATA_DISCLOSURE"],"Pedir uma foto de volta antes de enviar.":["RECIPROCAL_DISCLOSURE"],"Publicar a solicitação para todos responderem.":["SUSPICIOUS_REQUEST_AMPLIFIED"]},"position":5},{"id":"v5-comp-search-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"TITULO_CHAMATIVO_SEM_DATA","statement":"Um cartão diz “Descoberta incrível!” mas não mostra data nem quem o preparou. Qual conclusão é proporcional às pistas disponíveis?","options":["É uma descoberta verdadeira porque o título é animado.","É falso com certeza porque não mostra uma data.","A criança deve fornecer seus dados para ver a origem.","Não há informação suficiente para confirmar; compare com fonte indicada e peça ajuda."],"correctAnswer":"Não há informação suficiente para confirmar; compare com fonte indicada e peça ajuda.","explanation":"Falta de dados reduz o que se pode concluir, mas não prova automaticamente falsidade. A próxima etapa é conferir com apoio.","hint":"Evite concluir mais do que as pistas permitem.","errorFocus":"EVIDENCE_SCOPE_OVERCLAIM","misconceptions":{"É uma descoberta verdadeira porque o título é animado.":["TITLE_AS_EVIDENCE"],"É falso com certeza porque não mostra uma data.":["MISSING_CUE_AS_PROOF_OF_FALSEHOOD"],"A criança deve fornecer seus dados para ver a origem.":["PERSONAL_DATA_FOR_CONTENT"]},"position":6},{"id":"v5-comp-search-review-07","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"AJUDA_POR_CANAL_CONHECIDO","statement":"Uma criança não reconhece uma mensagem de acesso à biblioteca digital. Qual opção é melhor para pedir ajuda?","options":["Mostrar a mensagem a um adulto e usar o contato oficial já conhecido da escola.","Responder ao link com senha e código.","Perguntar a um perfil desconhecido encontrado numa busca.","Encaminhar para todos os contatos."],"correctAnswer":"Mostrar a mensagem a um adulto e usar o contato oficial já conhecido da escola.","explanation":"Um adulto e o contato oficial conhecido ajudam a verificar sem entregar credenciais a remetente desconhecido.","hint":"Use um caminho de ajuda que já foi confirmado, não um contato fornecido pela mensagem suspeita.","errorFocus":"KNOWN_CHANNEL_VERIFICATION","misconceptions":{"Responder ao link com senha e código.":["CREDENTIALS_SHARED_WITH_UNKNOWN"],"Perguntar a um perfil desconhecido encontrado numa busca.":["UNKNOWN_CONTACT_AS_HELP"],"Encaminhar para todos os contatos.":["SUSPICIOUS_REQUEST_AMPLIFIED"]},"position":7},{"id":"v5-comp-search-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EXPLAIN","contextFamily":"CITAR_FONTE_NO_TRABALHO","statement":"Uma criança usa uma página recomendada pelo professor para responder a uma pergunta. O que deve anotar para que outra pessoa encontre a fonte?","options":["Somente a cor do site.","O título ou nome da instituição e a data ou endereço fornecido pelo professor, conforme a atividade pedir.","A senha usada para abrir o computador.","O nome de uma pessoa aleatória."],"correctAnswer":"O título ou nome da instituição e a data ou endereço fornecido pelo professor, conforme a atividade pedir.","explanation":"Registrar dados básicos da fonte ajuda a localizar e conferir a informação. Senhas e dados pessoais não fazem parte da referência.","hint":"Anote pistas sobre o material, não credenciais.","errorFocus":"SOURCE_ATTRIBUTION_OMITTED","misconceptions":{"Somente a cor do site.":["VISUAL_DESIGN_AS_REFERENCE"],"A senha usada para abrir o computador.":["CREDENTIALS_AS_CITATION"],"O nome de uma pessoa aleatória.":["AUTHORSHIP_INVENTED"]},"position":8},{"id":"v5-comp-search-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"DECISAO_DE_NAO_CONTINUAR","statement":"A busca abre uma janela que pede endereço e senha, e a criança fica em dúvida. Qual explicação mostra que parar é uma boa decisão?","options":["Parar impede qualquer aprendizagem para sempre.","A janela deve ser preenchida porque apareceu durante a aula.","Parar protege informações e permite conferir com um adulto antes de decidir se a atividade é segura.","Uma senha pode ser compartilhada quando há dúvida."],"correctAnswer":"Parar protege informações e permite conferir com um adulto antes de decidir se a atividade é segura.","explanation":"Pausar diante de um pedido de dados reduz risco e cria oportunidade de verificar. Buscar ajuda é parte da competência digital.","hint":"Segurança pode ser a próxima etapa da tarefa, não uma interrupção do aprendizado.","errorFocus":"PAUSE_AND_ESCALATE","misconceptions":{"Parar impede qualquer aprendizagem para sempre.":["SAFETY_AS_FAILURE"],"A janela deve ser preenchida porque apareceu durante a aula.":["CONTEXT_AS_PERMISSION"],"Uma senha pode ser compartilhada quando há dúvida.":["PASSWORD_SHARING"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-computing-search-safe-browse',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-computing-search-safe-browse' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'COMPUTING', 'PESQUISA_DIGITAL', 'buscar informacao com ajuda e cuidado',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

